mapper.select:
SELECT mbbcnr.*, if(isnull(mbbcnr.mixed_job_ids), 0, (LENGTH(mbbcnr.mixed_job_ids) - LENGTH(REPLACE(mbbcnr.mixed_job_ids, ',', '')) + 1) > 1) AS is_mix_nest, mbmptd.device_name AS machine_tool_name, mbmptd.MID FROM mes_building_bo_chu_nesting_result mbbcnr LEFT JOIN mes_building_machine_part_team_detail mbmptd ON mbmptd.bool_delete_enum = 0 AND mbmptd.id = mbbcnr.machine_tool_id WHERE mbbcnr.bool_delete_enum = 0
AND mbbcnr.cut_send_status = #{cutSendStatus}
AND mbbcnr.job_id = #{jobId}
AND mbbcnr.thickness = #{thickness}
AND mbbcnr.material LIKE concat('%', #{material}, '%')
AND mbbcnr.cut_status = 0
AND mbbcnr.cut_status IN (1,2)

SELECT
    mbbcnr.*,
    if(isnull(mbbcnr.mixed_job_ids), 0, (LENGTH(mbbcnr.mixed_job_ids) - LENGTH(REPLACE(mbbcnr.mixed_job_ids, ',', '')) + 1) > 1) AS bool_mixed,
    mbmptd.device_name AS machine_tool_name,
    mbmptd.MID
FROM mes_building_bo_chu_nesting_result mbbcnr
LEFT JOIN mes_building_machine_part_team_detail mbmptd ON mbmptd.bool_delete_enum = 0 AND mbmptd.id = mbbcnr.machine_tool_id
WHERE mbbcnr.bool_delete_enum = 0

    AND mbbcnr.cut_send_status = #{cutSendStatus}


    AND date_format(mbbcnr.cut_send_time, #{cutSendTimeFormat}) >= date_format(#{cutSendTimeStart}, #{cutSendTimeFormat})


    AND date_format(mbbcnr.cut_send_time, #{cutSendTimeFormat}) <= date_format(#{cutSendTimeEnd}, #{cutSendTimeFormat})


    AND mbmptd.MID = #{mid}


    AND mbbcnr.cut_status = #{cutStatus}
